import java.util.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
public class Inspect{static ClassNode get(ZipFile z,String n)throws Exception{ClassNode c=new ClassNode();new ClassReader(z.getInputStream(z.getEntry(n+".class")).readAllBytes()).accept(c,0);return c;}public static void main(String[] a)throws Exception{try(ZipFile old=new ZipFile(a[0]);ZipFile fixed=new ZipFile(a[1])){ClassNode before=get(old,"net/flashlight/procedures/LightEventProcedure"),after=get(fixed,"net/flashlight/procedures/LightEventProcedure");String actual="";int match=0,nativeCalls=0;for(MethodNode m:before.methods)if(m.name.equals("onPlayerTick"))for(AbstractInsnNode i:m.instructions)if(i instanceof MethodInsnNode n&&n.name.equals("getEntity")){nativeCalls++;actual=n.desc;System.out.println("Native player accessor: "+n.owner+" "+n.desc);}for(MethodNode m:after.methods)if(m.name.equals("onPlayerTick"))for(AbstractInsnNode i:m.instructions)if(i instanceof MethodInsnNode n&&n.name.equals("getEntity")&&n.desc.equals(actual))match++;if(match!=nativeCalls+1)throw new AssertionError("Hook descriptor differs from native: "+match);for(String cl:new String[]{"FlashlightItem","FlashlightOFFItem"}){ClassNode item=get(fixed,"net/flashlight/item/"+cl);for(String method:new String[]{"isBarVisible","getBarWidth","getBarColor","appendHoverText"})if(item.methods.stream().filter(m->m.name.equals(method)).count()!=1)throw new AssertionError(method);}System.out.println("NATIVE_BATTERY_HOOK_CHECKS=9");}}}
